import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** A steward transfers the person to another sheet: they arrive with every grade given them (and its
 *  from-date), their terms, contact and aliases, and their claims with their status, dates, notes,
 *  tags, frozen figures, logs and comments; each claim that had a number gets the other sheet's next,
 *  in the order the claims were opened (by the sheet's today then, then the order they were added).
 *  Figures a statement bound are lost, their statement count starts at 0, and references, holds and
 *  settle batches are not carried. They leave this sheet entirely: patron links (either way), pool
 *  memberships, watches and closed periods' fixed totals are dropped. When someone on the other sheet
 *  already has their name or an alias (as names are compared), they are merged into that person
 *  there, as a merge does (see MergePerson): their claims after theirs, their name and aliases joined
 *  to theirs, the rest of them (contact included) dropped. Refused (nothing written) for anyone but a
 *  steward, a retired person, this sheet's own id or an archived sheet, when their names match more
 *  than one person there or a retired one, and (when not merged) when their contact is already there. */
public class TransferPerson {
    public void transfer(@RequestParam(name = "by", required = false) String by,
            @Val TransferRequest request, @Val Person person, PersonRepository people,
            ClaimRepository claims, PeriodRepository periods, RateRepository rates,
            SettingRepository settings, SheetRepository sheets, RoleRepository roles,
            Out<Transfer> transferred) throws InvalidPersonException {
        String user = by == null ? "" : by;
        String sheetId = person.getSheetId();
        String to = request.to();
        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
            throw new InvalidPersonException("Only a steward can transfer people");
        }
        if (to.equals(sheetId)) {
            throw new InvalidPersonException("A person cannot be transferred to their own sheet");
        }
        if (person.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be transferred");
        }
        if (sheets.isArchived(to)) {
            throw new InvalidPersonException("The sheet is archived: " + to);
        }
        Set<Long> matched = new LinkedHashSet<>();
        for (String name : names(person)) {
            Person match = people.findByName(to, name);
            if (match != null) {
                matched.add(match.getId());
            }
        }
        if (matched.size() > 1) {
            throw new InvalidPersonException("The name and aliases match more than one person on " + to);
        }
        Person into = matched.isEmpty() ? null : people.find(to, matched.iterator().next());
        if (into != null && into.isRetired()) {
            throw new InvalidPersonException("A retired person cannot be merged");
        }
        if (into == null && person.getContact() != null && people.contactTaken(to, person.getContact(), null)) {
            throw new InvalidPersonException("The contact is already on " + to);
        }
        sheets.open(to, user);
        Rollup before = Rollup.of(to, people, claims, rates, sheets, settings);
        for (long id : claims.transferAll(sheetId, person.getId(), to)) {
            Claim claim = claims.find(to, id);
            claims.renumber(claim, ClaimNumbers.next(claim, claims, periods, settings, sheets));
        }
        people.transfer(person, to);
        if (into != null) {
            Person arrived = people.find(to, person.getId());
            claims.moveAll(to, arrived.getId(), into.getId());
            people.merge(arrived, into, user);
        }
        transferred.set(new Transfer(person, to, before, into));
    }

    private static List<String> names(Person person) {
        List<String> names = new ArrayList<>();
        names.add(person.getName());
        names.addAll(person.getAliases());
        return names;
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.DatedSetting;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
 *  count live (open ones dated within a hold of theirs, and not bound, do not), n/a ones skipped, at most the sheet's cap; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force or dated on or before the sheet's today) on the sheet's today, and binds each counting claim
 *  to its rate figure under the due it shows now (its late charge and the floor are never bound); a claim that does not
 *  count live is unbound.
 *  <p>Taken as of a date ({@code asof}; blank: now) on or before the sheet's today, it goes by everything as it
 *  stood at the end of that date (every change made while the sheet's today was on or before it counts, every
 *  later one does not), that date standing in for the sheet's today: it records that day's due-total under that
 *  date and binds the claims that counted then to their figures then. Refused for a date after the sheet's
 *  today, or before the person was on the sheet. */
public class TakeStatement {
    public void take(@RequestParam(name = "asof", required = false) String asof, @Val Person person,
            PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings) throws InvalidPersonException {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate on = today;
        Person then = person;
        List<Claim> own;
        List<Rate> sheetRates;
        DatedSetting floor;
        Dues.Late late;
        BigDecimal cap;
        if (asof == null || asof.isBlank()) {
            own = claims.listOf(sheetId, person.getId());
            sheetRates = rates.list(sheetId);
            floor = settings.floor(sheetId);
            late = settings.late(sheetId, today);
            cap = settings.cap(sheetId);
        } else {
            try {
                on = LocalDate.parse(asof.trim());
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The statement date must be a date");
            }
            if (on.isAfter(today)) {
                throw new InvalidPersonException("The statement date cannot be after the sheet's today");
            }
            if (people.addedAfter(sheetId, person.getId(), on)) {
                throw new InvalidPersonException("The person was not on the sheet on the statement date");
            }
            then = people.findAsOf(sheetId, person.getId(), on);
            own = claims.listOfAsOf(sheetId, person.getId(), on);
            sheetRates = rates.listAsOf(sheetId, on);
            floor = settings.datedAsOf(sheetId, SettingRepository.FLOOR, SettingRepository.DEFAULT_FLOOR, on);
            late = settings.lateAsOf(sheetId, on);
            cap = settings.capAsOf(sheetId, on);
            person.setStatedAsOf(on.toString());
        }
        // The figure each counting claim is bound to, by claim id.
        Map<Long, String> figures = new HashMap<>();
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        for (Claim c : own) {
            if (!then.countsLive(c)) continue;
            String grade = then.gradeOn(c.getDate());
            Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate());
            String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
            String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
            kept |= c.getSettledDue() != null || c.isBound()
                    || (rate != null && (!grade.equals(then.getGrade())
                            || !LocalDate.parse(c.getDate()).isAfter(on)));
            if (shown != null) total = total.add(new BigDecimal(shown));
            // The rate figure under it is bound; its late charge and floor keep following the sheet's today.
            figures.put(c.getId(), c.due(live));
        }
        for (Claim c : claims.listOf(sheetId, person.getId())) {
            if (figures.containsKey(c.getId())) c.bind(true, figures.get(c.getId()));
            else c.bind(false, null);
            claims.updateBinding(c);
        }
        boolean na = RateRepository.inForce(sheetRates, then.getGrade(), on.toString()) == null && !kept;
        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
        person.stated(na ? null : total.toPlainString(), on.toString(), figures.size());
        people.updateStatements(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.Claim;
